// viewer.js — shared manual viewer.
//
// Each manual's index.html (generated by tools/build_viewers.py) holds the tree
// menu; this script wires up the original Workshop Manual 2 controls and adds
// modern ones:
//   - Back / Forward, TREE CLOSE / TREE OPEN, narrower / wider, RESET buttons
//     (with the original normal / hover / pressed button images)
//   - +/- and book icons that open and close with their section
//   - search, a draggable menu edge, and a remembered menu width
//   - one URL per document (#doc=…), so Back/Forward, reload and shared links work
//   - on phones, a slide-in menu; documents open in the phone's own PDF viewer
(function () {
  'use strict';

  var body = document.body;
  var root = document.documentElement;
  var frame = document.querySelector('.doc-frame');
  var welcome = document.querySelector('.welcome');
  var openCard = document.querySelector('.open-card');
  var tree = document.querySelector('.tree');
  var search = document.querySelector('.search');
  var status = document.querySelector('.search-status');
  var results = document.querySelector('.results');
  var splitter = document.querySelector('.splitter');
  var contentsBtn = document.querySelector('.contents-btn');
  var baseTitle = document.title;

  var MIN_WIDTH = 200;
  var DEFAULT_WIDTH = 260;
  var STEP = 50;
  var WIDTH_KEY = 'toyota-viewer-menu-width';
  var phone = window.matchMedia('(max-width: 767px)');

  // Browsers that can show a PDF inside the page. Phones (and Android in
  // particular) cannot, so there documents open in the system PDF viewer.
  function canShowInline() {
    return navigator.pdfViewerEnabled !== false && !phone.matches;
  }

  function storageGet(key) {
    try { return window.localStorage.getItem(key); } catch (e) { return null; }
  }

  function storageSet(key, value) {
    try { window.localStorage.setItem(key, value); } catch (e) { /* private mode etc. */ }
  }

  // ------------------------------------------------------------ image buttons
  // data-btn="reset" swaps reset1.gif (normal), reset2.gif (hover), reset3.gif (pressed).
  Array.prototype.forEach.call(document.querySelectorAll('[data-btn]'), function (btn) {
    var img = btn.querySelector('img');
    if (!img) return;
    function state(n) { img.src = img.src.replace(/[123]\.gif$/, n + '.gif'); }
    btn.addEventListener('pointerenter', function () { state(2); });
    btn.addEventListener('pointerleave', function () { state(1); });
    btn.addEventListener('pointerdown', function () { state(3); });
    btn.addEventListener('pointerup', function () { state(2); });
    btn.addEventListener('blur', function () { state(1); });
  });

  // ------------------------------------------------------------ tree icons
  document.addEventListener('toggle', function (event) {
    var details = event.target;
    if (!details.matches || !details.matches('.tree details')) return;
    Array.prototype.forEach.call(details.querySelectorAll(':scope > summary > img[data-open]'), function (img) {
      img.src = img.getAttribute(details.open ? 'data-open' : 'data-closed');
    });
  }, true);

  function collapseAll() {
    Array.prototype.forEach.call(tree.querySelectorAll('details[open]'), function (d) { d.open = false; });
    if (search.value) {
      search.value = '';
      runSearch();
    }
  }

  // ------------------------------------------------------------ menu width
  function maxWidth() {
    return Math.max(MIN_WIDTH, Math.round(window.innerWidth * 0.7));
  }

  function currentWidth() {
    return parseInt(getComputedStyle(root).getPropertyValue('--menu-w'), 10) || DEFAULT_WIDTH;
  }

  function setWidth(width, save) {
    width = Math.min(maxWidth(), Math.max(MIN_WIDTH, Math.round(width)));
    root.style.setProperty('--menu-w', width + 'px');
    if (save) storageSet(WIDTH_KEY, String(width));
  }

  var savedWidth = parseInt(storageGet(WIDTH_KEY), 10);
  if (savedWidth) setWidth(savedWidth, false);

  // Drag the menu's edge (pointer) or use the arrow keys on it.
  splitter.addEventListener('pointerdown', function (event) {
    event.preventDefault();
    splitter.setPointerCapture(event.pointerId);
    splitter.classList.add('dragging');
    body.classList.add('dragging');
    function move(e) { setWidth(e.clientX, false); }
    function up(e) {
      splitter.releasePointerCapture(e.pointerId);
      splitter.classList.remove('dragging');
      body.classList.remove('dragging');
      splitter.removeEventListener('pointermove', move);
      splitter.removeEventListener('pointerup', up);
      splitter.removeEventListener('pointercancel', up);
      setWidth(currentWidth(), true);
    }
    splitter.addEventListener('pointermove', move);
    splitter.addEventListener('pointerup', up);
    splitter.addEventListener('pointercancel', up);
  });

  splitter.addEventListener('keydown', function (event) {
    if (event.key === 'ArrowLeft') setWidth(currentWidth() - 20, true);
    else if (event.key === 'ArrowRight') setWidth(currentWidth() + 20, true);
    else return;
    event.preventDefault();
  });

  // ------------------------------------------------------------ phone drawer
  function setDrawer(open) {
    body.classList.toggle('drawer-open', open);
    contentsBtn.setAttribute('aria-expanded', String(open));
  }

  document.querySelector('.scrim').addEventListener('click', function () { setDrawer(false); });
  document.addEventListener('keydown', function (event) {
    if (event.key === 'Escape' && body.classList.contains('drawer-open')) setDrawer(false);
  });

  // ------------------------------------------------------------ buttons
  var actions = {
    back: function () { history.back(); },
    forward: function () { history.forward(); },
    narrower: function () { setWidth(currentWidth() - STEP, true); },
    wider: function () { setWidth(currentWidth() + STEP, true); },
    'tree-close': function () { body.classList.add('tree-closed'); },
    'tree-open': function () { body.classList.remove('tree-closed'); },
    reset: collapseAll,
    contents: function () { setDrawer(!body.classList.contains('drawer-open')); }
  };

  document.addEventListener('click', function (event) {
    var btn = event.target.closest && event.target.closest('[data-action]');
    if (btn && actions[btn.getAttribute('data-action')]) {
      event.preventDefault();
      actions[btn.getAttribute('data-action')]();
    }
  });

  // ------------------------------------------------------------ documents
  var links = Array.prototype.slice.call(tree.querySelectorAll('a[data-doc]'));
  var byHref = {};
  links.forEach(function (a) {
    var href = a.getAttribute('href');
    if (!byHref[href]) byHref[href] = a;
  });

  function textOf(el) {
    return (el ? el.textContent : '').replace(/\s+/g, ' ').trim();
  }

  function breadcrumb(a) {
    var parts = [];
    for (var el = a.parentElement; el && el !== tree; el = el.parentElement) {
      if (el.tagName === 'DETAILS') parts.unshift(textOf(el.querySelector(':scope > summary')));
    }
    return parts.join(' › ');
  }

  function markCurrent(href, reveal) {
    Array.prototype.forEach.call(document.querySelectorAll('a[aria-current]'), function (el) {
      el.removeAttribute('aria-current');
    });
    if (!href) return;
    Array.prototype.forEach.call(document.querySelectorAll('a[data-doc]'), function (el) {
      if (el.getAttribute('href') === href) el.setAttribute('aria-current', 'page');
    });
    var link = byHref[href];
    if (link && reveal) {
      for (var el = link.parentElement; el && el !== tree; el = el.parentElement) {
        if (el.tagName === 'DETAILS') el.open = true;
      }
      link.scrollIntoView({ block: 'nearest' });
    }
  }

  function docFromHash() {
    var m = /(?:^#|&)doc=([^&]+)/.exec(location.hash);
    if (!m) return null;
    try { return decodeURIComponent(m[1]); } catch (e) { return null; }
  }

  function show(reveal) {
    var href = docFromHash();
    var link = href && byHref[href];
    var title = link ? textOf(link) : href;
    document.title = title ? title + ' — ' + baseTitle : baseTitle;
    markCurrent(href, reveal);

    if (href && canShowInline()) {
      welcome.hidden = true;
      frame.hidden = false;
      body.classList.add('showing-doc');
      var url = new URL(href, location.href).href;
      // replace() keeps the frame out of the history; the #doc= hash is the history.
      if (frame.contentWindow) frame.contentWindow.location.replace(url);
      else frame.src = url;
      return;
    }

    body.classList.remove('showing-doc');
    frame.hidden = true;
    welcome.hidden = false;
    if (href) {
      openCard.hidden = false;
      openCard.querySelector('.open-title').textContent = title;
      var a = openCard.querySelector('a');
      a.href = href;
    } else {
      openCard.hidden = true;
    }
  }

  function openDoc(href) {
    var hash = '#doc=' + encodeURIComponent(href);
    if (location.hash === hash) show(false);
    else location.hash = hash;
  }

  document.addEventListener('click', function (event) {
    var a = event.target.closest && event.target.closest('a[data-doc]');
    if (!a || event.button !== 0 || event.ctrlKey || event.metaKey || event.shiftKey || event.altKey) return;
    var href = a.getAttribute('href');
    if (canShowInline()) {
      event.preventDefault();
      openDoc(href);
    } else {
      // Let the link open the PDF in the phone's viewer (new tab); just mark it.
      markCurrent(href, false);
    }
  });

  window.addEventListener('hashchange', function () { show(true); });

  // ------------------------------------------------------------ search
  var MAX_RESULTS = 200;
  var index = links.map(function (a) {
    var crumb = breadcrumb(a);
    return { link: a, crumb: crumb, haystack: (textOf(a) + ' ' + crumb).toLowerCase() };
  });

  function runSearch() {
    var terms = search.value.toLowerCase().split(/\s+/).filter(Boolean);
    results.textContent = '';
    if (!terms.length) {
      body.classList.remove('searching');
      results.hidden = true;
      status.hidden = true;
      return;
    }
    body.classList.add('searching');
    var matches = index.filter(function (entry) {
      return terms.every(function (t) { return entry.haystack.indexOf(t) !== -1; });
    });
    matches.slice(0, MAX_RESULTS).forEach(function (entry) {
      var li = document.createElement('li');
      var copy = entry.link.cloneNode(true);
      li.appendChild(copy);
      if (entry.crumb) {
        var crumb = document.createElement('span');
        crumb.className = 'crumb';
        crumb.textContent = entry.crumb;
        li.appendChild(crumb);
      }
      results.appendChild(li);
    });
    results.hidden = false;
    status.hidden = false;
    status.textContent = !matches.length ? 'No matches.' :
      matches.length > MAX_RESULTS ? 'Showing the first ' + MAX_RESULTS + ' of ' + matches.length + ' matches.' :
      matches.length + (matches.length === 1 ? ' match.' : ' matches.');
  }

  search.addEventListener('input', runSearch);
  search.addEventListener('keydown', function (event) {
    if (event.key === 'Escape' && search.value) {
      event.stopPropagation();
      search.value = '';
      runSearch();
    }
  });

  // ------------------------------------------------------------ start
  show(true);
  if (phone.matches && !docFromHash()) setDrawer(true);
})();
